import bisect

class Solution:
    def aggregateTimeSeries(self, series1: list[list[int]], series2: list[list[int]]) -> list[list[int]]:
        timestamps1 = [ts for ts, val in series1]
        timestamps2 = [ts for ts, val in series2]

        all_timestamps = sorted(set(timestamps1 + timestamps2))

        aggregated = []

        for ts in all_timestamps:
            # Get value from series1
            val1 = 0
            idx = bisect.bisect_left(timestamps1, ts)
            if idx < len(timestamps1) and timestamps1[idx] == ts:
                val1 = series1[idx][1]
            else:
                if idx < len(timestamps1):
                    val1 = series1[idx][1]

            # Get value from series2
            val2 = 0
            idx = bisect.bisect_left(timestamps2, ts)
            if idx < len(timestamps2) and timestamps2[idx] == ts:
                val2 = series2[idx][1]
            else:
                if idx < len(timestamps2):
                    val2 = series2[idx][1]

            aggregated.append([ts, val1 + val2])

        return aggregated
